            while(!stackIn.isEmpty()){
                int value = stackIn.pop();
                stackOut.push(value);
            }
        }
        return stackOut.peek();
    }

    public boolean empty() {
        return stackOut.isEmpty() && stackIn.isEmpty();
    }
}

