class Solution {
    public int mySqrt(int x) {
        long l = 1;
        long r = x;
        while(l <= r){
            long m = l + (r - l) / 2;
            if(m * m == x){
                return (int)m;
            }
            else if(m*m < x){
                l = m + 1;
            }
            else{
                r = m - 1;
            }
        }
        return (int)l-1;
    }
}

